CREATE TABLE payment_ledger (ledger_entry_id VARCHAR(200) PRIMARY KEY,effect_id VARCHAR(300) NOT NULL,entry_type VARCHAR(50) NOT NULL,amount DECIMAL(18,2) NOT NULL,currency VARCHAR(10) NOT NULL,debit_account VARCHAR(200),credit_account VARCHAR(200),ledger_time TIMESTAMP NOT NULL,processor_time TIMESTAMP,settlement_time TIMESTAMP,dispute_time TIMESTAMP,state VARCHAR(50) NOT NULL,state_hash VARCHAR(300) NOT NULL,provider_reference VARCHAR(200),policy_version VARCHAR(100),replay_card_id VARCHAR(200),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_payment_ledger_effect ON payment_ledger(effect_id);
